import{d as c,C as t,o as u,c as b,j as a,a as o,E as n,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第三章","description":"从不尚贤、不贵货、不见可欲，辨认欲望竞争与无为之治的关系。","frontmatter":{"title":"道德经第三章","description":"从不尚贤、不贵货、不见可欲，辨认欲望竞争与无为之治的关系。","category":"guide","aliases":["道德经第三章","老子第三章","dao de jing chapter 3"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-03.md","filePath":"daoism/dao-de-jing/chapter-03.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-03.md"},y=c({...m,setup(x){const i=[{id:"honours-goods-and-desire",label:"不尚贤，使民不争",showLabel:!0,sentences:[["不",{text:"尚",glossary:"shang"},"贤，使民不争；"],["不",{text:"贵",glossary:"gui"},"难得之货，使民不为盗；"],["不",{text:"见",glossary:"xian"},"可欲，使民心不乱。"]],note:["【白话】不把贤能之名抬得过高，使百姓不竞相争夺；不把难得的财货看得过分贵重，使百姓不至于为它偷盗；不炫示足以引起贪欲的东西，使人心不被搅乱。","【王弼注择要】「贤犹能也」，又说「尚贤显名，荣过其任」。王弼区分任用能力与抬高名位，所批评的是荣名超过实际职任、贵货超过实际用途。","【读法】「见」读 xiàn，作显现、展示解。「不尚贤」不能简单译成不用贤能；但它确实在反省以名位驱动竞争的治理方式。"]},{id:"heart-belly-will-and-bones",label:"虚其心，实其腹",showLabel:!0,sentences:[["是以圣人之治，虚其心，实其腹，"],["弱其志，强其骨。"]],note:["【白话】所以，圣人的治理，是让百姓的心少些机巧与欲求，让肚腹得到充实；削弱争逐的意向，增强身体的筋骨。","【王弼注择要】「心怀智而腹怀食」，又说「志生事以乱」。心、腹、志、骨构成对照：减少生事的机巧与争逐，充实维持生活的根本。","【读法】「弱其志」所针对的并非现代意义上一切志向。这段也不只是个人养生，它仍在说治理者怎样影响百姓的生活与心志。"]},{id:"knowledge-desire-and-governance",label:"为无为，则无不治",showLabel:!0,sentences:[["常使民",{text:"无知",glossary:"wuzhi"},{text:"无欲",glossary:"wuyu"},"。"],["使夫",{text:"知",glossary:"zhi"},"者不敢为也。"],["为",{text:"无为",glossary:"wuwei"},"，则无不治。"]],note:["【白话】常使百姓保持少机巧、少贪求的状态，使那些善用智巧的人不敢妄为。以无为的方式施行治理，就没有不能治理好的。","【王弼注择要】「守其真也。」「知者谓知为也。」注把无知无欲连到守真，把知者连到善于施为的人，重心在机巧造作。","【读法】这里的知与智巧相通，不能只按现代的信息知识来读；也不能因此消去「使民」所包含的治理权力。末句是本章提出的理想，不能当作适用于所有制度的效果保证。"]}],r=[{id:"shang",term:"尚",sense:1},{id:"gui",term:"贵",sense:1},{id:"xian",term:"见",sense:1,pinyin:"xiàn",context:"「不见可欲」中的见作显现、展示解，读 xiàn。"},{id:"wuzhi",term:"无知",sense:1},{id:"wuyu",term:"无欲",sense:1,context:"此章在使民守真的治理语境中使用，指少贪求，不是要求取消基本生活需要。"},{id:"zhi",term:"知",sense:1,pinyin:"zhì",context:"知者的知与智相通，指善于机巧施为，读 zhì。"},{id:"wuwei",term:"无为",sense:1,context:"与不炫名、不贵货相连，强调减少人为刺激与机巧干预。"}];return(g,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第三章",tabindex:"-1"},[o("道德经第三章 "),a("a",{class:"header-anchor",href:"#道德经第三章","aria-label":'Permalink to "道德经第三章"'},"​")],-1)),n(s,{title:"先看争欲怎样被激起",summary:"第三章把第二章对标举一端的警惕，落到名位、财货与治理。先看什么使人争逐，再读虚心实腹、无知无欲；既辨认王弼对智巧的批评，也保留对治理权力的追问。",points:[{label:"先读",text:"不尚、不贵、不见，分别减少什么刺激？"},{label:"再辨",text:"虚心与实腹、弱志与强骨为何成对？"},{label:"后想",text:"如何区分减少造作与限制人的自主？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[o("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),n(l,{sections:i,glossary:r,tone:"ink",density:"comfortable","aria-label":"《道德经》第三章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[o("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"不尚贤，使民不争。",tone:"辨名",guide:"王弼以荣名超过实际职任解释争的来源。任用能力与制造人人争夺的荣名，应先分开讨论。"},{text:"虚其心，实其腹，弱其志，强其骨。",tone:"辨本",guide:"这组对照把生活供养与争逐心志分开。若只讲减欲而忽略实腹强骨，就遗漏了本章对实际生活的要求。"},{text:"常使民无知无欲。",tone:"辨权",guide:"不能把无知直接读成反对一切学习，也不能只用保持纯真轻轻带过使民二字。它包含古代治理者对百姓状态的安排，须带着历史距离阅读。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[o("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),n(h,{items:r}),e[4]||(e[4]=p('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-本章为什么把争、盗、乱放在一起" tabindex="-1">象：本章为什么把争、盗、乱放在一起？ <a class="header-anchor" href="#象-本章为什么把争、盗、乱放在一起" aria-label="Permalink to &quot;象：本章为什么把争、盗、乱放在一起？&quot;">​</a></h3><p>三种问题分别承接名位的标举、珍货的抬价和可欲之物的炫示。它们把注意力从事后的惩治，移向欲望怎样被社会环境激起。王弼所说「荣过其任」「贵货过用」，尤其指出名与物超过实际用途后带来的争逐。</p><h3 id="理-「无知无欲」只是在赞美天真吗" tabindex="-1">理：「无知无欲」只是在赞美天真吗？ <a class="header-anchor" href="#理-「无知无欲」只是在赞美天真吗" aria-label="Permalink to &quot;理：「无知无欲」只是在赞美天真吗？&quot;">​</a></h3><p>王弼以守真、减少智巧解释这句话，但原文的主语仍是治理者，动作是「使民」。这与一个人自愿减少贪求并不完全相同。理解古注能够避免把知一概读成知识，却不能替文本消除权力上的张力：谁来界定机巧，谁有权决定别人应当知道什么？</p><h3 id="用-今天可以怎样借鉴「实其腹」" tabindex="-1">用：今天可以怎样借鉴「实其腹」？ <a class="header-anchor" href="#用-今天可以怎样借鉴「实其腹」" aria-label="Permalink to &quot;用：今天可以怎样借鉴「实其腹」？&quot;">​</a></h3><p>可以先检查生活保障与激励设计，而不急着责备个体欲望过多。例如，组织是否一面奖励过度竞争，一面要求成员平和？借鉴的起点是减少无谓攀比、改善实际条件；不应借无知无欲压制教育、知情与独立判断。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>先看环境奖励什么。</strong> 一个团队若只公开排名、不讨论实际贡献，容易让人把精力放在争夺可见的名次。调整激励与评价方式，比只劝大家不争更接近本章提出问题的方向。</p><p><strong>减欲不能代替保障。</strong> 面对消费攀比，可以减少炫耀性刺激；面对基本生活不足，则需要改善供养。把这两类问题分清，才不至于让「知足」成为忽视现实需要的理由。这是现代议题的借鉴，不等于把古代治理主张直接移植成制度。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我最近追求的一项名位或物品，有多少来自实际需要，又有多少来自外部比较？若减少比较，我仍需要哪些具体支持？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>「不见可欲」的见读 xiàn，作显现解；「知者」的知与智相通，依智巧解读。</li><li>「使民心不乱」保留本站原有通行文字；HFL 电子录文作「使心不乱」，没有「民」字。</li><li>本章同时有减轻争逐的思路与治理者安排民心的立场；引申时须保留这种张力。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，002b–003a</a>。</p>',15))])}}});export{_ as __pageData,y as default};
